  "test": {
  description: "cargo nextest run (macOS/Windows native, else Linux host if dev libs present, else container)",
  run: { shell: "node --input-type=module-typescript -e", run: "\nconst { execFileSync } = await import('node:child_process')\nconst { globSync } = await import('node:fs')\nconst onPath = (command) => { try { execFileSync('which', [command], { stdio: 'ignore' }); return true } catch { return false } }\nconst pkgConfigOk = () => { try { execFileSync('pkg-config', ['--exists', 'libpipewire-0.3', 'fontconfig', 'freetype2'], { stdio: 'ignore' }); return true } catch { return false } }\nconst hostOk = onPath('cargo') && pkgConfigOk()\nconst hostEnv = () => {\n  const clangDirs = globSync('/usr/lib/clang/*').sort()\n  const resourceDir = clangDirs[clangDirs.length - 1]\n  return { ...process.env, LIBCLANG_PATH: '/usr/lib64', BINDGEN_EXTRA_CLANG_ARGS: `-resource-dir=${resourceDir}` }\n}\nconst defaultContainer = { image: 'localhost/monochromatic/music-player', containerfile: 'Containerfile', cargoVolume: 'music-player-cargo', limits: [], env: [], program: 'cargo' }\n// CACHYOS_IMAGE is the CachyOS image this host's CPU level supports (cachyos-v4, -v3 or plain), resolved by the repository's\n// cachyos-image command; it throws on a host that is not x86-64, because these images have no Alpine variant.\nconst cachyosBuildArguments = (imageName) => ['--build-arg', execFileSync('node', [process.getBuiltinModule('node:path').resolve(process.cwd(), '../../test-harness/core-matrix/src/bin/cachyos-image.ts'), '--image-name', imageName, '--build-argument'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'inherit'] }).trim()]\nconst containerCargo = (cargoArgs, containerOptions = {}) => {\n  const container = { ...defaultContainer, ...containerOptions }\n  let imageExists = true\n  try { execFileSync('podman', ['image', 'exists', container.image], { stdio: 'ignore' }) } catch { imageExists = false }\n  if (!imageExists) { execFileSync('podman', ['build', ...cachyosBuildArguments(container.image.split('/').pop()), '-t', container.image, '-f', container.containerfile, '.'], { stdio: 'inherit' }) }\n  // Forward SLINT_EMIT_DEBUG_INFO into the container ONLY when the caller set it\n  // (the test + mcp tasks do). podman does not inherit host env, and the\n  // ElementHandle / MCP introspection APIs refuse to run without this debug info.\n  // Production build tasks never set it, so their container binaries stay lean.\n  const debugInfoEnv = process.env.SLINT_EMIT_DEBUG_INFO ? ['-e', 'SLINT_EMIT_DEBUG_INFO=1'] : []\n  // The crate reads two paths outside its own directory, and the container mounts only the package directory at\n  // /work, so each is mounted read-only where the same relative path from /work finds it: ../truepeak-core is the\n  // Cargo path dependency, and ../android-app/app/src/test/resources holds the theme-roles-vector.txt fixture that\n  // src/theme_roles_fixture_tests.rs compares with the Rust derivation. A missing source fails here by name, never\n  // as a skipped test or a bare podman statfs error. The repository's root clippy.toml (the fleet-wide ban on\n  // Result::unwrap) is mounted at /clippy.toml: clippy searches the ancestors of /work, so the container lint runs\n  // with the same rules as the host lint (issue 1756).\n  const { resolve } = process.getBuiltinModule('node:path')\n  const { existsSync } = process.getBuiltinModule('node:fs')\n  const siblingMounts = [['../truepeak-core', '/truepeak-core'], ['../android-app/app/src/test/resources', '/android-app/app/src/test/resources'], ['../../../clippy.toml', '/clippy.toml']]\n  const siblingMountArgs = siblingMounts.flatMap(([relative, inside]) => {\n    const host = resolve(process.cwd(), relative)\n    if (!existsSync(host)) { throw new Error(`containerCargo needs ${host} (mounted read-only at ${inside}) but it does not exist; run the task from the checked-out package/music-player/desktop-app directory of a full checkout`) }\n    return ['-v', `${host}:${inside}:ro`]\n  })\n  execFileSync('podman', ['run', '--rm', ...container.limits, '--security-opt', 'label=disable', ...debugInfoEnv, ...container.env, '-v', `${process.cwd()}:/work`, ...siblingMountArgs, '-v', `${container.cargoVolume}:/cargo`, '-w', '/work', container.image, container.program, ...cargoArgs], { stdio: 'inherit' })\n}\nconst runCargo = (cargoArgs) => {\n  if (process.platform !== 'linux') { execFileSync('cargo', cargoArgs, { stdio: 'inherit' }) }\n  else if (hostOk) { execFileSync('cargo', cargoArgs, { stdio: 'inherit', env: hostEnv() }) }\n  else { containerCargo(cargoArgs) }\n}\n\nprocess.env.SLINT_EMIT_DEBUG_INFO = '1'\nrunCargo(['nextest', 'run'])", },
  },
