  "test:alpine": {
  description: "Alpine (musl) guard in podman, the same commands as the test-alpine job of .github/workflows/music-player-release.yml: build Containerfile.alpine, cargo nextest, build the app and the nested compositor, then the three smoke scenarios (no sound, ALSA, PipeWire)",
  run: { shell: "node --input-type=module-typescript -e", run: "const { execFileSync } = await import('node:child_process')\nconst { mkdirSync } = await import('node:fs')\nconst { join, resolve } = await import('node:path')\nconst packageDir = process.cwd()\nconst musicPlayer = resolve(packageDir, '..')\nconst compositor = resolve(packageDir, '../../nested-wayland-session/cli')\nconst cache = join(packageDir, 'target', 'alpine-cache')\nfor (const sub of ['cargo', 'target-app', 'target-nws', 'scratch', 'smoke-out', 'context']) { mkdirSync(join(cache, sub), { recursive: true }) }\nconst podman = (args) => execFileSync('podman', args, { stdio: 'inherit' })\nfor (const target of ['build', 'smoke']) {\n  podman(['build', '--target', target, '--tag', `music-player-alpine-${target}`, '--file', 'Containerfile.alpine', join(cache, 'context')])\n}\nconst bounds = ['--memory=12g', '--cpus=4', '--security-opt', 'label=disable']\nconst appMounts = ['--volume', `${musicPlayer}:/src:ro`, '--volume', `${join(cache, 'cargo')}:/cargo`, '--volume', `${join(cache, 'target-app')}:/target`]\nconst appEnv = ['--env', 'CARGO_HOME=/cargo', '--env', 'CARGO_TARGET_DIR=/target', '--env', 'CARGO_INCREMENTAL=0', '--env', 'CARGO_PROFILE_DEV_DEBUG=0', '--env', 'SLINT_EMIT_DEBUG_INFO=1', '--env', 'SLINT_ENABLE_EXPERIMENTAL_FEATURES=1']\npodman(['run', '--rm', ...bounds, ...appMounts, '--volume', `${join(cache, 'scratch')}:/src/desktop-app/target`, ...appEnv, '--workdir', '/src/desktop-app', 'music-player-alpine-build', 'cargo', 'nextest', 'run', '--locked', '--features', 'alsa-fallback', '--no-fail-fast'])\npodman(['run', '--rm', ...bounds, ...appMounts, ...appEnv, '--workdir', '/src/desktop-app', 'music-player-alpine-build', 'cargo', 'build', '--locked', '--features', 'alsa-fallback'])\npodman(['run', '--rm', ...bounds, '--volume', `${compositor}:/src:ro`, '--volume', `${join(cache, 'cargo')}:/cargo`, '--volume', `${join(cache, 'target-nws')}:/target`, '--env', 'CARGO_HOME=/cargo', '--env', 'CARGO_TARGET_DIR=/target', '--env', 'CARGO_INCREMENTAL=0', '--env', 'CARGO_PROFILE_RELEASE_LTO=false', '--env', 'CARGO_PROFILE_RELEASE_CODEGEN_UNITS=16', '--workdir', '/src', 'music-player-alpine-build', 'cargo', 'build', '--release', '--locked'])\npodman(['run', '--rm', '--memory=4g', '--cpus=4', '--security-opt', 'label=disable', '--volume', `${join(cache, 'target-app', 'debug', 'music-player')}:/opt/music-player/music-player:ro`, '--volume', `${join(cache, 'target-nws', 'release', 'monochromatic-nested-wayland-session')}:/opt/music-player/nws:ro`, '--volume', `${join(packageDir, 'fixture')}:/opt/music-player/fixture:ro`, '--volume', `${join(cache, 'smoke-out')}:/tmp/smoke-out`, 'music-player-alpine-smoke', 'music-player-smoke'])\nconsole.error(`smoke screenshots and logs: ${join(cache, 'smoke-out')}`)", },
  },
